</div>

@code {
    private static readonly string[] StepLabels = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; } = 1;
    private string _errorMessage = string.Empty;

    // Step 1
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;
    private bool _isValidating;

    // Step 2
    private List<WorkEntryModel> _workEntries = new() { new() };

    // Step 3
    private List<ReferenceModel> _references = new() { new() };

    // Step 4
    private string _coverLetter = string.Empty;
    private const int CoverLetterMaxLength = 2000;

    // Step 5
    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;

    // ── Navigation ──

    private void GoToStep(int step)
    {
        if (step < CurrentStep && !_submitted)
        {
            _errorMessage = string.Empty;
            CurrentStep = step;
        }
    }

    // ── Step 1 ──

    private async Task NextFromStep1()
    {
        _errorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(_fullName) ||
            string.IsNullOrWhiteSpace(_email) ||
            string.IsNullOrWhiteSpace(_phone) ||
            string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Please fill in all required fields.";
            return;
        }

        _isValidating = true;
        try
        {
            var valid = await ApplicationService.ValidateEmailAsync(_email);
            if (!valid)
            {
                _errorMessage = "Please enter a valid email address.";
                return;
            }
            CurrentStep = 2;
        }
        finally
        {
            _isValidating = false;
        }
    }

    // ── Step 2 ──

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index) => _workEntries.RemoveAt(index);

    private void UpdateWork(int index, WorkEntryModel updated) => _workEntries[index] = updated;

    private void NextFromStep2()
    {
        _errorMessage = string.Empty;

        foreach (var e in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(e.Company) ||
                string.IsNullOrWhiteSpace(e.Title) ||
                e.StartDate == default)
            {
                _errorMessage = "Please fill in company, job title, and start date for every position.";
                return;
            }
        }

        CurrentStep = 3;
    }

    // ── Step 3 ──

    private void AddReference()
    {
        if (_references.Count < 3) _references.Add(new ReferenceModel());
    }

    private void UpdateRef(int index, ReferenceModel updated) => _references[index] = updated;

    private void NextFromStep3()
    {
        _errorMessage = string.Empty;

        if (_references.Count < 2)
        {
            _errorMessage = "Please provide at least 2 references.";
            return;
        }

        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) ||
                string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) ||
                string.IsNullOrWhiteSpace(r.Phone))
            {
                _errorMessage = "Please fill in all fields for every reference.";
                return;
            }
        }

        CurrentStep = 4;
    }

    // ── Step 5 ──

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _errorMessage = string.Empty;

        try
        {
            var personal = new PersonalInfo(_fullName.Trim(), _email.Trim(), _phone.Trim(), _address.Trim());
            var workHistory = new WorkHistory(_workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var references = _references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(personal, workHistory, references, _coverLetter);
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch
        {
            _errorMessage = "An error occurred while submitting your application. Please try again.";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    // ── Mutable view-models for form binding ──

    private record WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private record ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

