@page "/apply"
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h2 class="mb-4">Job Application</h2>

    @* ───── Step Indicator Bar ───── *@
    <nav class="step-indicator mb-4" aria-label="Application steps">
        @for (int i = 0; i < StepLabels.Length; i++)
        {
            var step = i + 1;
            var status = step < CurrentStep ? "completed"
                       : step == CurrentStep ? "active"
                       : "future";
            <button class="step-item @status"
                    disabled="@(status == "future" || _submitted)"
                    @onclick="() => GoToStep(step)">
                <span class="step-circle">
                    @if (status == "completed")
                    {
                        <span class="step-check">✓</span>
                    }
                    else
                    {
                        @step
                    }
                </span>
                <span class="step-label">@StepLabels[step - 1]</span>
            </button>
            @if (i < StepLabels.Length - 1)
            {
                <span class="step-connector @(step < CurrentStep ? "completed" : "")"></span>
            }
        }
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger" role="alert">@_errorMessage</div>
    }

    @* ───── Step 1: Personal Info ───── *@
    @if (CurrentStep == 1)
    {
        <section>
            <h4>Personal Information</h4>

            <div class="mb-3">
                <label class="form-label" for="fullName">Full Name <span class="text-danger">*</span></label>
                <input id="fullName" class="form-control" @bind="_fullName" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="email">Email <span class="text-danger">*</span></label>
                <input id="email" type="email" class="form-control" @bind="_email" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="phone">Phone <span class="text-danger">*</span></label>
                <input id="phone" type="tel" class="form-control" @bind="_phone" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="address">Address <span class="text-danger">*</span></label>
                <input id="address" class="form-control" @bind="_address" />
            </div>

            <div class="d-flex justify-content-end">
                <button class="btn btn-primary" @onclick="NextFromStep1" disabled="@_isValidating">
                    @if (_isValidating) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Next
                </button>
            </div>
        </section>
    }

    @* ───── Step 2: Work History ───── *@
    else if (CurrentStep == 2)
    {
        <section>
            <h4>Work History</h4>

            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var idx = i;
                var entry = _workEntries[idx];
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h6 class="mb-0">Position @(idx + 1)</h6>
                            @if (_workEntries.Count > 1)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(idx)">Remove</button>
                            }
                        </div>

                        <div class="row g-3">
                            <div class="col-md-6">
                                <label class="form-label">Company <span class="text-danger">*</span></label>
                                <input class="form-control" value="@entry.Company"
                                       @onchange="e => UpdateWork(idx, entry with { Company = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                <input class="form-control" value="@entry.Title"
                                       @onchange="e => UpdateWork(idx, entry with { Title = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-4">
                                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                <input type="date" class="form-control" value="@entry.StartDate.ToString("yyyy-MM-dd")"
                                       @onchange="e => UpdateWork(idx, entry with { StartDate = DateTime.Parse((string?)e.Value ?? string.Empty) })" />
                            </div>
                            <div class="col-md-4">
                                <label class="form-label">End Date</label>
                                <input type="date" class="form-control"
                                       disabled="@entry.IsCurrent"
                                       value="@(entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty)"
                                       @onchange="e => UpdateWork(idx, entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
                            </div>
                            <div class="col-md-4 d-flex align-items-end">
                                <div class="form-check mb-2">
                                    <input type="checkbox" class="form-check-input" id="@($"current-{idx}")"
                                           checked="@entry.IsCurrent"
                                           @onchange="e => UpdateWork(idx, entry with { IsCurrent = (bool)(e.Value ?? false), EndDate = (bool)(e.Value ?? false) ? null : entry.EndDate })" />
                                    <label class="form-check-label" for="@($"current-{idx}")">Currently working here</label>
                                </div>
                            </div>
                            <div class="col-12">
                                <label class="form-label">Description</label>
                                <textarea class="form-control" rows="2" value="@entry.Description"
                                          @onchange="e => UpdateWork(idx, entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
                            </div>
                        </div>
                    </div>
                </div>
            }

            <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">
                + Add Another Position
            </button>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="() => CurrentStep--">Back</button>
                <button class="btn btn-primary" @onclick="NextFromStep2">Next</button>
            </div>
        </section>
    }

    @* ───── Step 3: References ───── *@
    else if (CurrentStep == 3)
    {
        <section>
            <h4>References</h4>

            @for (int i = 0; i < _references.Count; i++)
            {
                var idx = i;
                var refEntry = _references[idx];
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h6 class="mb-0">Reference @(idx + 1)</h6>
                            @if (_references.Count > 1)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => _references.RemoveAt(idx)">Remove</button>
                            }
                        </div>
                        <div class="row g-3">
                            <div class="col-md-6">
                                <label class="form-label">Name <span class="text-danger">*</span></label>
                                <input class="form-control" value="@refEntry.Name"
                                       @onchange="e => UpdateRef(idx, refEntry with { Name = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Relationship <span class="text-danger">*</span></label>
                                <input class="form-control" value="@refEntry.Relationship"
                                       @onchange="e => UpdateRef(idx, refEntry with { Relationship = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Email <span class="text-danger">*</span></label>
                                <input type="email" class="form-control" value="@refEntry.Email"
                                       @onchange="e => UpdateRef(idx, refEntry with { Email = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Phone <span class="text-danger">*</span></label>
                                <input type="tel" class="form-control" value="@refEntry.Phone"
                                       @onchange="e => UpdateRef(idx, refEntry with { Phone = (string?)e.Value ?? string.Empty })" />
                            </div>
                        </div>
                    </div>
                </div>
            }

            @if (_references.Count < 3)
            {
                <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
                    + Add Reference
                </button>
            }

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="() => CurrentStep--">Back</button>
                <button class="btn btn-primary" @onclick="NextFromStep3">Next</button>
            </div>
        </section>
    }

    @* ───── Step 4: Cover Letter ───── *@
    else if (CurrentStep == 4)
    {
        <section>
            <h4>Cover Letter</h4>

            <div class="mb-2">
                <textarea class="form-control" rows="10" maxlength="2000"
                          @bind="_coverLetter" @bind:event="oninput"></textarea>
            </div>
            <div class="text-muted mb-3">@_coverLetter.Length / 2000 characters</div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="() => CurrentStep--">Back</button>
                <button class="btn btn-primary" @onclick="() => CurrentStep++">Next</button>
            </div>
        </section>
    }

    @* ───── Step 5: Review & Submit ───── *@
    else if (CurrentStep == 5)
    {
        <section>
            @if (_submitted)
            {
                <div class="text-center py-5">
                    <div class="mb-3" style="font-size:3rem;">✅</div>
                    <h4>Application Submitted!</h4>
                    <p class="text-muted">Your application ID is <strong>@_applicationId</strong>.</p>
                    <p>Thank you for applying. We will review your application and get back to you soon.</p>
                </div>
            }
            else
            {
                <h4>Review Your Application</h4>

                @* Personal Info *@
                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>Personal Information</strong>
                        <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(1)">Edit</button>
                    </div>
                    <div class="card-body">
                        <dl class="row mb-0">
                            <dt class="col-sm-3">Full Name</dt><dd class="col-sm-9">@_fullName</dd>
                            <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                            <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                            <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                        </dl>
                    </div>
                </div>

                @* Work History *@
                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>Work History</strong>
                        <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(2)">Edit</button>
                    </div>
                    <div class="card-body">
                        @foreach (var entry in _workEntries)
                        {
                            <div class="mb-3">
                                <strong>@entry.Title</strong> at @entry.Company<br />
                                <span class="text-muted">
                                    @entry.StartDate.ToString("MMM yyyy") –
                                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                                </span>
                                @if (!string.IsNullOrWhiteSpace(entry.Description))
                                {
                                    <p class="mt-1 mb-0">@entry.Description</p>
                                }
                            </div>
                        }
                    </div>
                </div>

                @* References *@
                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>References</strong>
                        <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(3)">Edit</button>
                    </div>
                    <div class="card-body">
                        @foreach (var r in _references)
                        {
                            <div class="mb-2">
                                <strong>@r.Name</strong> — @r.Relationship<br />
                                <span class="text-muted">@r.Email · @r.Phone</span>
                            </div>
                        }
                    </div>
                </div>

                @* Cover Letter *@
                <div class="card mb-3">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>Cover Letter</strong>
                        <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(4)">Edit</button>
                    </div>
                    <div class="card-body">
                        <p style="white-space:pre-wrap;">@_coverLetter</p>
                    </div>
                </div>

                <div class="d-flex justify-content-between">
                    <button class="btn btn-secondary" @onclick="() => CurrentStep--">Back</button>
                    <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
                        @if (_isSubmitting) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Submit Application
                    </button>
                </div>
            }
        </section>
    }
</div>

